/** Loopback-only event adapter for production plugin regression; never distribute. */
public final class FollowupProbe extends JavaPlugin {
 final Gson json=new Gson();
 JavaPlugin game(String name){return (JavaPlugin)Bukkit.getPluginManager().getPlugin(name);}
 public void onEnable(){if(!Bukkit.getIp().equals("127.0.0.1"))throw new IllegalStateException("Loopback only");Bukkit.getMessenger().registerIncomingPluginChannel(this,"kasaba_test:followup",(ch,p,data)->{if(data.length>2048||p.getAddress()==null||!p.getAddress().getAddress().isLoopbackAddress())return;String op=new String(data,StandardCharsets.UTF_8);String[] a=op.split("\\|",-1);try{var race=game("KasabaYaris");var prison=game("KasabaHapis");var sp=game("KasabaIspanya");var vk=game("KasabaVampirKoylu");Object room;switch(a[0]){
 case "STATE"->{Map<String,Object> d=new LinkedHashMap<>();HubApi hub=Bukkit.getServicesManager().load(HubApi.class);d.put("uuid",p.getUniqueId());d.put("world",p.getWorld().getName());d.put("mode",p.getGameMode());d.put("social",hub.socialArea(p.getUniqueId()));d.put("playing",hub.playing(p.getUniqueId()));d.put("vehicle",p.getVehicle()==null?null:p.getVehicle().getType());d.put("versions",Bukkit.getPluginManager().getPlugins().length);var guard=Bukkit.getServicesManager().load(GameAccessGuard.class);d.put("blocked",guard!=null&&guard.blocked(p.getUniqueId()));Object jail=((Map<?,?>)get(prison,"sentences")).get(p.getUniqueId());d.put("cell",jail==null?-1:get(jail,"cell"));d.put("expires",jail==null?0:get(jail,"expiresAt"));d.put("admin",p.hasPermission("kasabatr.hapis.admin"));d.put("floor",p.getLocation().clone().subtract(0,1,0).getBlock().getType());d.put("jailCount",((Map<?,?>)get(prison,"sentences")).size());room=member(race,p);if(room!=null){Map<String,Object> r=new LinkedHashMap<>();r.put("id",get(room,"id"));r.put("mode",get(room,"mode").toString());r.put("state",get(room,"state").toString());r.put("owner",get(room,"owner"));r.put("size",((Map<?,?>)get(room,"racers")).size());Object rider=((Map<?,?>)get(room,"racers")).get(p.getUniqueId());Entity mount=(Entity)get(rider,"mount");r.put("mount",mount==null?null:mount.getType());r.put("valid",mount!=null&&mount.isValid());r.put("dnf",get(rider,"dnf"));r.put("passenger",mount!=null&&mount.getPassengers().contains(p));Object progress=get(rider,"progress");r.put("lap",progress==null?0:call(progress,"lap"));r.put("checkpoint",progress==null?0:call(progress,"nextCheckpoint"));r.put("complete",progress!=null&&Boolean.TRUE.equals(call(progress,"complete")));d.put("race",r);}d.put("raceRooms",((Map<?,?>)get(race,"rooms")).size());d.put("raceWorlds",Bukkit.getWorlds().stream().map(World::getName).filter(n->n.startsWith("yaris_room_")).toList());say(p,"state:"+json.toJson(d));}
 case "RACE_GATE"->{room=member(race,p);Object rider=((Map<?,?>)get(room,"racers")).get(p.getUniqueId());Entity mount=(Entity)get(rider,"mount");Object course=call(call(race,"map"),"course",get(room,"mode"));Object gate=a[1].equals("finish")?call(course,"finish"):((List<?>)call(course,"checkpoints")).get(Integer.parseInt(a[1]));double x=(double)call(gate,"x"),y=(double)call(gate,"y"),z=(double)call(gate,"z");set(rider,"lastX",x-2);set(rider,"lastGateTick",-100L);call(race,"moveMount",mount,new Location((World)get(room,"world"),x,y,z));Object targetRoom=room;Bukkit.getScheduler().runTaskLater(this,()->{try{set(rider,"lastX",x-2);set(rider,"lastGateTick",-100L);call(targetRoom,"tick");}catch(Exception e){say(p,"error:"+e);}},2);}
 case "RACE_END"->{room=member(race,p);set(room,"resultTicks",1);call(room,"tick");}
 case "RACE_GUARDS"->{var dis=new EntityDismountEvent(p,p.getVehicle());Bukkit.getPluginManager().callEvent(dis);BlockBreakEvent broken=new BlockBreakEvent(p.getLocation().clone().subtract(0,1,0).getBlock(),p);Bukkit.getPluginManager().callEvent(broken);var hurt=new EntityDamageEvent(p,EntityDamageEvent.DamageCause.FALL,5);Bukkit.getPluginManager().callEvent(hurt);say(p,"guards:"+json.toJson(Map.of("dismount",dis.isCancelled(),"break",broken.isCancelled(),"damage",hurt.isCancelled())));}
 case "JAIL_GUARDS"->{Location old=p.getLocation();var move=new PlayerMoveEvent(p,old,old.clone().add(40,0,0));Bukkit.getPluginManager().callEvent(move);var command=new PlayerCommandPreprocessEvent(p,"/lobi");Bukkit.getPluginManager().callEvent(command);var gm=new PlayerGameModeChangeEvent(p,GameMode.CREATIVE);Bukkit.getPluginManager().callEvent(gm);var tp=new PlayerTeleportEvent(p,old,Bukkit.getWorlds().getFirst().getSpawnLocation());Bukkit.getPluginManager().callEvent(tp);var broken=new BlockBreakEvent(old.clone().subtract(0,1,0).getBlock(),p);Bukkit.getPluginManager().callEvent(broken);var chat=new AsyncPlayerChatEvent(false,p,"Should be blocked",new HashSet<>(Bukkit.getOnlinePlayers()));Bukkit.getPluginManager().callEvent(chat);say(p,"guards:"+json.toJson(Map.of("move",move.isCancelled(),"command",command.isCancelled(),"mode",gm.isCancelled(),"teleport",tp.isCancelled(),"break",broken.isCancelled(),"chat",chat.isCancelled())));}
 case "JAIL_EXPIRE"->{Player target=Bukkit.getPlayerExact(a[1]);Object sentence=((Map<?,?>)get(prison,"sentences")).get(target.getUniqueId());set(sentence,"expiresAt",System.currentTimeMillis()-1000);call(prison,"saveData");call(prison,"tick");}
 case "SP_STATE"->{room=member(sp,p);Map<String,Object> d=new LinkedHashMap<>();d.put("room",room==null?null:get(room,"id"));d.put("world",p.getWorld().getName());d.put("items",Arrays.stream(p.getInventory().getContents()).map(i->i==null?"AIR":i.getType().name()).toList());if(room!=null){for(String field:List.of("active","current","movingId","positions","skippedTurns","missedRolls","pendingShortcut","skipping","ending","endCountdown","turnLeft","effectSeconds"))d.put(field,get(room,field));d.put("effect",get(room,"pendingEffect")!=null);Object layout=get(room,"layout");if(layout!=null){d.put("kinds",get(layout,"kinds"));d.put("shortcuts",get(layout,"shortcuts"));}}say(p,"state:"+json.toJson(d));}
 case "SP_POSITION"->{room=member(sp,p);int index=Integer.parseInt(a[1]);((Map<UUID,Integer>)get(room,"positions")).put(p.getUniqueId(),index);Object tile=call(call(sp,"track"),"tile",index);call(sp,"teleport",p,call(tile,"location",get(room,"world")));set(room,"current",p.getUniqueId());set(room,"pendingEffect",null);set(room,"pendingShortcut",null);set(room,"skipping",false);call(room,"stopAnimation");call(sp,"removeShortcut",p);}
 case "SP_SEED"->{room=member(sp,p);int sum=Integer.parseInt(a[1]);boolean luck=a.length<3||Boolean.parseBoolean(a[2]);long seed;for(seed=0;;seed++){Random random=new Random(seed);if(random.nextInt(6)+random.nextInt(6)+2==sum&&(a.length<3||random.nextBoolean()==luck))break;}((Random)get(room,"random")).setSeed(seed);}
 case "SP_DRAIN"->{room=member(sp,p);for(int i=0;i<2000&&get(room,"movingId")!=null;i++)call(room,"moveStep");}
 case "SP_TICK"->{room=member(sp,p);for(int i=0;i<Integer.parseInt(a[1]);i++)call(room,"tick");}
 case "SP_TIMEOUT"->{room=member(sp,p);set(room,"current",p.getUniqueId());set(room,"turnLeft",1);call(room,"tick");}
 case "SP_END"->{room=member(sp,p);call(room,"beginEnding","Test sonuçları");}
 case "VK_VOTE"->{room=member(vk,p);if(!get(room,"phase").toString().equals("VOTE"))call(room,"beginVote");else call(vk,"openTargetMenu",p,room,"vote");}
 case "VK_FLAGS"->{room=member(vk,p);set(room,"seer",Boolean.parseBoolean(a[1]));set(room,"doctor",Boolean.parseBoolean(a[2]));set(room,"hunter",Boolean.parseBoolean(a[3]));}
 case "VK_VOTES"->{room=member(vk,p);say(p,"votes:"+json.toJson(get(room,"votes")));}
 case "ROLE_COLORS"->{var roles=game("KasabaRoles");Object role=call(roles,"role",p.getName());say(p,"colors:"+json.toJson(Map.of("tag",call(role,"color"),"name",call(role,"nameColor"),"message",call(role,"chatColor"))));}
 case "ARENA_LATE"->{var arena=game("KasabaArena");String old=arena.getConfig().saveToString();String disk=java.nio.file.Files.readString(arena.getDataFolder().toPath().resolve("config.yml"));World test=Bukkit.createWorld(new WorldCreator("kasaba_late_probe").generator(new org.bukkit.generator.ChunkGenerator(){public boolean shouldGenerateNoise(){return false;}public boolean shouldGenerateSurface(){return false;}public boolean shouldGenerateBedrock(){return false;}public boolean shouldGenerateCaves(){return false;}public boolean shouldGenerateDecorations(){return false;}public boolean shouldGenerateStructures(){return false;}}));Map<String,Object> point=Map.of("world",test.getUID().toString(),"worldName",test.getName(),"x",0.5,"y",80.0,"z",0.5);test.getBlockAt(0,79,0).setType(Material.STONE);test.setSpawnLocation(0,80,0);test.save();Bukkit.unloadWorld(test,true);arena.getConfig().createSection("spawns.lobi",point);call(arena,"loadLocations");boolean missing=get(arena,"lobbySpawn")==null;Bukkit.createWorld(new WorldCreator("kasaba_late_probe"));Bukkit.getScheduler().runTaskLater(this,()->{try{boolean ready=get(arena,"lobbySpawn") instanceof Location l&&l.getWorld().getName().equals("kasaba_late_probe");arena.getConfig().loadFromString(old);call(arena,"loadLocations");say(p,"late:"+json.toJson(Map.of("missingBeforeLoad",missing,"readyAfterLoad",ready,"fileUnchanged",disk.equals(java.nio.file.Files.readString(arena.getDataFolder().toPath().resolve("config.yml"))))));}catch(Exception e){say(p,"error:"+e);}},3);}
 default->throw new IllegalArgumentException(op);}
 say(p,"done:"+op);}catch(Throwable e){say(p,"error:"+e);getLogger().log(java.util.logging.Level.SEVERE,"Followup fixture",e);}});}
 Object enumValue(Object previous,String value){return Enum.valueOf((Class)previous.getClass(),value);}
 Object member(Object plugin,Player p)throws Exception{return ((Map<?,?>)get(plugin,"membership")).get(p.getUniqueId());}
 Object get(Object target,String name)throws Exception{Field f=target.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(target);}
 void set(Object target,String name,Object value)throws Exception{Field f=target.getClass().getDeclaredField(name);f.setAccessible(true);f.set(target,value);}
 Object call(Object target,String name,Object... args)throws Exception{Method m=Arrays.stream(target.getClass().getDeclaredMethods()).filter(x->x.getName().equals(name)&&x.getParameterCount()==args.length).filter(x->{for(int i=0;i<args.length;i++)if(args[i]!=null&&!x.getParameterTypes()[i].isPrimitive()&&!x.getParameterTypes()[i].isInstance(args[i]))return false;return true;}).findFirst().orElseThrow();m.setAccessible(true);return m.invoke(target,args);}
 void say(Player p,String text){p.sendMessage(net.kyori.adventure.text.Component.text("followup-probe:"+text));}
}
